 const single=[28,29,32,33,37,38,55,62].includes(g),same=[54,57,61,65].includes(g),out=g>=40&&g<=53||g===67,work=[56,66].includes(g);
 function arrow(id,x,y,dx){const end=x+dx;return`<path id="${id}" d="M${x} ${y}H${end}" stroke="#6558c8" stroke-width="4" fill="none"/><path id="${id}-head" d="M${end-Math.sign(dx)*9} ${y-6}L${end} ${y}L${end-Math.sign(dx)*9} ${y+6}" fill="none" stroke="#6558c8" stroke-width="3"/>`;}
 if(g===63){start=225;body+=`<circle id="track" cx="180" cy="100" r="70" stroke="#bdd4f1" stroke-width="12" fill="none"/><path id="lap-direction" d="M180 30A70 70 0 0 1 250 100" fill="none" stroke="#6558c8" stroke-width="4"/><path id="lap-head" d="M244 90L250 100L256 90" stroke="#6558c8" stroke-width="3" fill="none"/>`+txt('lap-length',180,110,v[0]+' м',23);}
